using System.Globalization;
using System.Xml.Linq;

namespace AoMDivineDataEditor.Classes;

/// <summary>Field-aware ownership for strings generated by the Command editor.</summary>
internal static class ProtoUnitCommandStringPolicy
{
    internal static IReadOnlyList<string> FieldTags { get; } = Array.AsReadOnly(new[]
    {
        "displaynameid", "rollovertextid", "shortrollovertextid", "activerollovertextid",
        "disabledrollovertextid", "buildlimittextid"
    });

    internal static string BuildId(string name, string tag)
    {
        var token = new string(name.Trim().ToUpperInvariant()
            .Select(character => char.IsLetterOrDigit(character) ? character : '_').ToArray());
        while (token.Contains("__", StringComparison.Ordinal)) token = token.Replace("__", "_", StringComparison.Ordinal);
        var suffix = tag.ToLowerInvariant() switch
        {
            "displaynameid" => "NAME", "rollovertextid" => "LR", "shortrollovertextid" => "SR",
            "activerollovertextid" => "ACTIVE_LR", "disabledrollovertextid" => "DISABLED_LR",
            "buildlimittextid" => "BUILD_LIMIT", _ => tag.ToUpperInvariant()
        };
        return $"STR_PUC_{token.Trim('_')}_{suffix}";
    }

    internal static IReadOnlySet<string> CollectOwnedStringIds(XElement command)
        => OwnedMappings(command, Name(command)).Keys.ToHashSet(StringComparer.OrdinalIgnoreCase);

    internal static IReadOnlyList<OwnedStringRename> RenameOwnedStringIds(XElement before,
        XElement candidate, string newName, IReadOnlySet<string> availableSourceIds)
    {
        var mappings = OwnedMappings(before, newName);
        var result = new List<OwnedStringRename>();
        foreach (var field in Fields(candidate))
        {
            var oldId = field.Value.Trim();
            if (!availableSourceIds.Contains(oldId) || !mappings.TryGetValue(oldId, out var newId) ||
                oldId.Equals(newId, StringComparison.OrdinalIgnoreCase)) continue;
            XmlTriviaPreserver.SetText(field, newId);
            result.Add(new(field.Name.LocalName, oldId, newId));
        }
        return result;
    }

    private static Dictionary<string, string> OwnedMappings(XElement command, string newName)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var name = Name(command);
        if (command.Name.Namespace != XNamespace.None ||
            !command.Name.LocalName.Equals("protounitcommand", StringComparison.OrdinalIgnoreCase) || name.Length == 0) return result;
        foreach (var field in Fields(command))
        {
            var id = field.Value.Trim();
            var basis = BuildId(name, field.Name.LocalName);
            if (!id.StartsWith(basis, StringComparison.OrdinalIgnoreCase)) continue;
            var suffix = id[basis.Length..];
            // The editor allocates the base ID, then _2, _3, ...; no other prefix match proves ownership.
            if (suffix.Length != 0 && !(suffix.StartsWith('_') &&
                    int.TryParse(suffix.AsSpan(1), NumberStyles.None, CultureInfo.InvariantCulture, out var index) &&
                    index >= 2 && "_" + index.ToString(CultureInfo.InvariantCulture) == suffix)) continue;
            result[id] = BuildId(newName, field.Name.LocalName) + suffix;
        }
        return result;
    }

    private static string Name(XElement command) => command.Elements().FirstOrDefault(field =>
        field.Name.Namespace == XNamespace.None && field.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase))?.Value.Trim() ?? "";

    private static IEnumerable<XElement> Fields(XElement command) => command.Elements().Where(field =>
        field.Name.Namespace == XNamespace.None && !field.HasElements &&
        FieldTags.Contains(field.Name.LocalName, StringComparer.OrdinalIgnoreCase));
}
